<script setup>
import {ref,computed,watch,onUnmounted} from 'vue';
import BaseModal from '../components/BaseModal.vue';
import {state,api,scope,useResource,notify,changed,ask,can,captureContext,contextMatches} from '../lib/workspace';
import {normalized} from '../lib/format';
const props=defineProps({kind:{type:String,required:true}});
const accountant=props.kind==='accountant',routine=accountant?'accounting.accountants':'fiscal.shared_parties';
const title=accountant?'Contadores':'Terceiros',base=`/registrations/${props.kind}`;
const {data,error:loadError}=useResource(()=>api(scope(base)),[]);
const query=ref(''),form=ref(null),error=ref(''),busy=ref(false);
let context=null,baseline='';
const filtered=computed(()=>data.value.filter(r=>normalized(`${r.name} ${r.tax_id} ${r.data.crc||''}`).includes(normalized(query.value))));
const manage=computed(()=>state.session?.user?.role==='admin');
const canUse=computed(()=>accountant?can(routine,'edit'):can('fiscal.masters','create'));
const usedHere=row=>row.links.some(l=>l.company_id===state.companyId);
function edit(row=null){context=captureContext();form.value=JSON.parse(JSON.stringify(row||{name:'',tax_id:'',active:true,data:{category:'accountant'}}));baseline=JSON.stringify(form.value);error.value='';state.editor={name:title,companyId:context.companyId};}
function dismiss(){form.value=null;state.editor=null;}
async function close(){if(busy.value)return;if(form.value&&baseline!==JSON.stringify(form.value)&&!await ask({title:'Descartar edição?',message:'Há alterações cadastrais não salvas.',confirmLabel:'Descartar'}))return;dismiss();}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{await api(scope(base+(form.value.id?`/${form.value.id}`:''),context.companyId),{method:form.value.id?'PUT':'POST',body:form.value,context});if(contextMatches(context)){dismiss();changed();notify('Cadastro compartilhado salvo.');}}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function useHere(row){if(busy.value)return;const ctx=captureContext();busy.value=true;try{await api(scope(`${base}/${row.id}/use`,ctx.companyId),{method:'POST',body:{version:row.version},context:ctx});if(contextMatches(ctx)){changed();notify('Cadastro disponível para uso na empresa ativa.');}}catch(e){notify(e.message,'error');}finally{busy.value=false;}}
async function deactivate(row){if(busy.value)return;const ctx=captureContext();if(!await ask({title:'Desativar cadastro compartilhado?',message:'O cadastro será desativado para novos vínculos. Cadastros locais e documentos existentes serão preservados.',confirmLabel:'Desativar',danger:true}))return;busy.value=true;try{await api(scope(`${base}/${row.id}`,ctx.companyId),{method:'DELETE',body:{version:row.version},context:ctx});changed();notify('Cadastro desativado.');}catch(e){notify(e.message,'error');}finally{busy.value=false;}}
watch(()=>[state.companyId,state.period,state.module],()=>{if(form.value)dismiss();},{flush:'sync'});
onUnmounted(()=>{if(form.value)state.editor=null;});
</script>
<template><div class="view"><header class="view-heading"><div><div class="eyebrow">CADASTROS</div><h1>{{title}}</h1><p>Catálogo global disponível às empresas autorizadas desta instalação, sem vínculo prévio para consulta.</p></div><button class="button primary" v-if="manage" :disabled="busy" @click="edit()">{{accountant?'Novo contador':'Novo terceiro'}}</button></header>
<p class="message subtle">A consulta global tem permissão própria. A manutenção do catálogo é reservada ao administrador. Use o cadastro na empresa ativa quando necessário.{{accountant?'':' Os dados da escrituração e os vínculos locais são preservados; atualizações globais não sobrescrevem documentos nem cadastros locais.'}}</p>
<div v-if="loadError" class="message error" role="alert">{{loadError}}</div><section class="panel"><div class="table-toolbar"><input v-model="query" :placeholder="accountant?'Nome, CPF ou CRC':'Nome ou CPF/CNPJ'" aria-label="Pesquisar cadastros compartilhados"/></div><div class="table-scroll"><table><thead><tr><th>Nome</th><th>{{accountant?'CPF':'CPF/CNPJ'}}</th><th v-if="accountant">CRC / UF</th><th>Uso nas empresas</th><th>Situação</th><th>Ações</th></tr></thead><tbody><tr v-for="row in filtered" :key="row.id"><td>{{row.name}}</td><td>{{row.tax_id||'Não informado'}}</td><td v-if="accountant">{{row.data.crc}} / {{row.data.crc_state}}</td><td><div v-for="item in row.links" :key="item.company_id">{{state.companies.find(c=>c.id===item.company_id)?.name||'Empresa autorizada'}}</div></td><td>{{row.active?'Ativo':'Inativo'}}</td><td><div class="actions"><button class="button small" :disabled="busy" @click="edit(row)">{{manage?'Editar':'Consultar'}}</button><button class="button small" v-if="row.active&&canUse&&!usedHere(row)" :disabled="busy" @click="useHere(row)">Usar nesta empresa</button><button class="button small" v-if="row.active&&manage" :disabled="busy" @click="deactivate(row)">Desativar</button></div></td></tr><tr v-if="!filtered.length"><td :colspan="accountant?6:5">Nenhum cadastro encontrado no catálogo global.</td></tr></tbody></table></div></section>
<BaseModal v-if="form" :title="`${form.id?(manage?'Editar':'Consultar'):'Novo'} ${accountant?'contador':'terceiro'}`" @close="close"><p v-if="error" class="message error" role="alert">{{error}}</p><form id="shared-registration" @submit.prevent="save"><fieldset class="form-grid" :disabled="!manage"><label>Nome *<input v-model="form.name" required maxlength="250"/></label><label>{{accountant?'CPF *':'CPF/CNPJ'}}<input v-model="form.tax_id" :required="accountant" :readonly="!!form.id"/></label><label>Situação<select v-model="form.active"><option :value="true">Ativo</option><option :value="false">Inativo</option></select></label><template v-if="accountant"><label>CRC *<input v-model="form.data.crc" required/></label><label>UF do CRC *<input v-model="form.data.crc_state" required maxlength="2"/></label><label>Categoria profissional *<select v-model="form.data.category"><option value="accountant">Contador</option><option value="technician">Técnico em contabilidade</option></select></label></template><template v-else><label>Nome fantasia<input v-model="form.data.trade_name"/></label><label>Logradouro<input v-model="form.data.address"/></label><label>Número<input v-model="form.data.number"/></label><label>Bairro<input v-model="form.data.district"/></label><label>Município<input v-model="form.data.city"/></label><label>UF<input v-model="form.data.state" maxlength="2"/></label><label>CEP<input v-model="form.data.postal_code"/></label></template><label>E-mail<input v-model="form.data.email" type="email"/></label><label>Telefone<input v-model="form.data.phone"/></label></fieldset></form><template #footer><button class="button" :disabled="busy" @click="close">Cancelar</button><button v-if="manage" class="button primary" :disabled="busy" form="shared-registration">Salvar cadastro</button></template></BaseModal>

</div></template>
<style scoped>
fieldset.form-grid{border:0;padding:0;margin:0;min-width:0}
</style>
